 */
export function MessageList({ messages, loading, messagesEndRef, config }) {
  return (
    <Box 
      sx={{ 
        flex: 1, 
        overflowY: 'auto', 
        borderRadius: 2,
        p: 1,
        mb: 1,
        bgcolor: 'white',
        display: 'flex',
        flexDirection: 'column'
      }}
