      <TextField
        variant="outlined"
        fullWidth
        placeholder="Digite sua mensagem..."
        value={input}
        onChange={onChange}
        onKeyPress={onKeyPress}
        multiline
        maxRows={3}
        disabled={loading}
        sx={{
          '& .MuiOutlinedInput-root': {
            borderRadius: 2,
            fontSize: '0.95rem'
