102	      // Using the Evolution API directly with the provided configuration
103	      const evoBaseUrl = 'https://evolution-api-production-ad04.up.railway.app';
104	      const evoApiKey = '429683C4C977415CAAFCCE10F7D57E11'; // This would normally be stored in backend
105	      
106	      // Make API call to generate QR code using the format from the curl command:
107	      // curl -H "apikey:$EVO_KEY" "$EVO_BASE/instance/connect/teste?number=$MY_PHONE"
108	      const response = await fetch(`${evoBaseUrl}/instance/connect/${instanceName}?number=${phoneNumber}`, {
109	        method: 'GET',
110	        headers: {
111	          'apikey': evoApiKey
112	        }
113	      });
114	      
115	      if (!response.ok) {
116	        throw new Error(`Evolution API responded with status ${response.status}`);
117	      }
118	      
119	      const data = await response.json();
120	      
121	      console.log("Evolution API response:", data);
122	      
123	      // The API returns the qr string directly in the response
124	      if (data.qrcode && data.qrcode.base64) {
125	        // Set QR code from base64 data provided by Evolution API
