            onClick={handleBack}
            aria-label="back"
            sx={{ mr: 2 }}
          >
            <ArrowBackIcon />
          </IconButton>
          <Typography variant="h6" sx={{ flexGrow: 1, fontWeight: 'bold', letterSpacing: 0.5 }}>
            Configurações da Conta
          </Typography>

          <Button
            color="inherit"
            variant="outlined"
            onClick={handleSave}
            sx={{ borderRadius: 2 }}
          >
            Salvar
          </Button>
        </Toolbar>

        <Tabs
          value={tabValue}
          onChange={handleTabChange}
          indicatorColor="secondary"
          textColor="inherit"
          variant="scrollable"
          scrollButtons="auto"
          aria-label="settings tabs"
          sx={{ 
            bgcolor: 'primary.dark',
            '& .MuiTab-root': { 
              minWidth: 120, 
              fontSize: '0.875rem', 
